// Hand-written. Not generated by Speakeasy.
//
// Authlete returns several lists in an order of its own choosing rather than
// the order they were written in. Terraform compares lists by position, so a
// permutation reads as a change: the plan offers to rewrite the list, the apply
// succeeds, Authlete returns its own order again, and the next plan offers the
// same change. It never converges.
//
// These are sets in everything but their OpenAPI spelling. Nothing about a
// grant type or a response mode depends on its position.
//
// The obvious fix is a custom list type implementing semantic equality, which
// is how the JWK Set attributes next door solve the same shape of problem.
// That does not work here: x-speakeasy-terraform-custom-type is applied to
// string properties and silently ignored on arrays, so the generated model
// keeps a plain []types.String and the framework never has a type to ask. This
// was tried and the generated schema came back unchanged.
//
// A plan modifier reaches the same end by a different route. Rather than
// teaching the framework that two orders are equal, it keeps the order already
// in state whenever the configuration lists the same elements, so the plan has
// nothing to show.
package planmodifiers

import (
	"context"
	"sort"

	"github.com/hashicorp/terraform-plugin-framework/attr"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/planmodifier"
)

// KeepOrderWhenUnchanged returns a plan modifier for a list Authlete reorders.
func KeepOrderWhenUnchanged() planmodifier.List { return keepOrderWhenUnchanged{} }

type keepOrderWhenUnchanged struct{}

func (m keepOrderWhenUnchanged) Description(_ context.Context) string {
	return "keeps the order already in state when the configuration lists the same " +
		"elements, because Authlete returns this list in an order of its own and " +
		"Terraform compares lists by position"
}

func (m keepOrderWhenUnchanged) MarkdownDescription(ctx context.Context) string {
	return m.Description(ctx)
}

func (m keepOrderWhenUnchanged) PlanModifyList(ctx context.Context, req planmodifier.ListRequest, resp *planmodifier.ListResponse) {
	// Creation has no prior order to keep.
	if req.State.Raw.IsNull() {
		return
	}

	// Null or unknown on either side is a real difference, or not yet knowable.
	if req.StateValue.IsNull() || req.StateValue.IsUnknown() {
		return
	}
	if req.ConfigValue.IsNull() || req.ConfigValue.IsUnknown() {
		return
	}

	// Only a permutation is suppressed. Anything else is a genuine change and
	// must plan normally, or a real edit would be silently dropped.
	if SameElements(ctx, req.StateValue.Elements(), req.ConfigValue.Elements()) {
		resp.PlanValue = req.StateValue
	}
}

// SameElements reports whether two element slices hold the same values,
// counting duplicates, in any order.
//
// A multiset rather than a set: a list that genuinely contains a value twice is
// not the same as one that contains it once, and collapsing them would hide a
// real difference.
func SameElements(ctx context.Context, a, b []attr.Value) bool {
	if len(a) != len(b) {
		return false
	}

	keys := func(vals []attr.Value) ([]string, bool) {
		out := make([]string, 0, len(vals))
		for _, val := range vals {
			tfVal, err := val.ToTerraformValue(ctx)
			if err != nil {
				return nil, false
			}
			out = append(out, tfVal.String())
		}
		sort.Strings(out)
		return out, true
	}

	ka, ok := keys(a)
	if !ok {
		return false
	}
	kb, ok := keys(b)
	if !ok {
		return false
	}

	for i := range ka {
		if ka[i] != kb[i] {
			return false
		}
	}
	return true
}
